export function schedule(expression, callback) {
  // Simple periodic runner that runs every hour (or every 60s for testing)
  const timer = setInterval(() => {
    try {
      callback();
    } catch (e) {
      console.error('[node-cron error]', e);
    }
  }, 60 * 60 * 1000);

  return {
    start: () => {},
    stop: () => clearInterval(timer)
  };
}

export default {
  schedule
};
